const input = $input.first().json;
const userInput = input.chatInput || input.question || '';

// Patterns d'injection connus
const dangerousPatterns = [
  /ignore\s+(all\s+)?previous\s+instructions?/gi,
  /ignore\s+(all\s+)?prior\s+instructions?/gi,
  /forget\s+(all\s+)?previous\s+instructions?/gi,
  /you\s+are\s+now\s+/gi,
  /disregard\s+(all\s+|your\s+)?instructions?/gi,
  /override\s+(all\s+)?instructions?/gi,
  /jailbreak/gi,
  /DAN\s+mode/gi,
  /act\s+as\s+(if\s+)?you\s+(are|were|have\s+no)/gi,
  /system\s+prompt\s*:/gi,
  /print\s+(your\s+)?(system|original)\s+prompt/gi,
  /reveal\s+(your\s+)?(instructions?|prompt|system)/gi,
  /<\s*script[^>]*>/gi,
  /javascript\s*:/gi,
  /\beval\s*\(/gi
];

const flags = [];
for (const pattern of dangerousPatterns) {
  if (pattern.test(userInput)) {
    flags.push(pattern.source);
  }
}

const lengthOk = userInput.length <= 2000;
const patternOk = flags.length === 0;

return [{
  json: {
    original_input: userInput,
    is_safe: patternOk && lengthOk,
    flags_detected: flags,
    length_ok: lengthOk,
    char_count: userInput.length,
    check_method: 'regex'
  }
}];

const guardResult = $input.first().json;
const guardText = (guardResult.text || guardResult.output || '').trim().toLowerCase();
const isSafe = guardText.startsWith('safe');

return [{
  json: {
    is_safe: isSafe,
    guard_response: guardText,
    check_method: 'llama-guard3',
    original_input: $('Regex Security Check').first().json.original_input
  }
}];

// Input est sûr, on retourne avec le contexte de sécurité
const securityData = $input.first().json;
return [{ json: {
  validated_input: securityData.original_input,
  security_checks: {
    regex: true,
    semantic: securityData.check_method === 'llama-guard3' ? securityData.is_safe : null
  },
  status: 'approved'
} }];

const input = $('Regex Security Check').first().json;
return [{ json: {
  status: 'rejected',
  reason: 'Prompt injection détectée ou contenu non autorisé',
  flags: input.flags_detected,
  length_ok: input.length_ok,
  message: 'Votre message a été bloqué pour des raisons de sécurité. Merci de reformuler votre question.'
} }];
